xref <- function(label) {
  if (knitr::is_html_output()) {
    sprintf("\\@ref(fig:html%s)", label)
  } else {
    sprintf("\\@ref(fig:latex%s)", label)
  }
}

# Helper: format inline code for HTML vs LaTeX (handles underscores safely in LaTeX)
code_fmt <- function(x) {
  x <- unname(x)
  if (knitr::is_latex_output()) {
    # In source strings we often write \$ to keep R parsing happy.
    # For LaTeX code output we want the literal dollar sign.
    x <- gsub("\\$", "$", x, fixed = TRUE)
    sprintf("\\texttt{\\detokenize{%s}}", x)
  } else {
    # Keep dollars safe for HTML math parsing while displaying as '$'.
    x <- gsub("\\$", "&#36;", x, fixed = TRUE)
    x <- gsub("$", "&#36;", x, fixed = TRUE)
    sprintf("<code>%s</code>", x)
  }
}

combined_p_value <- function(x) {
  if (inherits(x, "ldmppr_model_check")) {
    s <- summary(x)
    return(as.numeric(s$p_combined))
  }
  p <- attr(x, "p", exact = TRUE)
  if (is.null(p)) return(NA_real_)
  as.numeric(p)
}

fmt_lists <- function(s) {
  s <- unname(s)

  vapply(s, FUN.VALUE = character(1), function(one) {
    one <- unname(one)

    if (!grepl("\\[\\[(ul|ol|ol-a)\\]\\]", one, perl = TRUE)) return(one)

    lines <- strsplit(one, "\n", fixed = TRUE)[[1]]
    out <- character(0)

    mode <- NULL  # "ul", "ol", "ol-a"
    buf <- character(0)

    extract_item <- function(ln) {
      ln <- sub("^\\s*[-*]\\s+", "", ln)          # "- item"
      ln <- sub("^\\s*\\d+[\\.)]\\s+", "", ln)   # "1. item" or "1) item"
      ln
    }

    flush_list <- function(items, mode) {
      items <- vapply(items, extract_item, character(1))
      items <- items[nzchar(trimws(items))]

      if (mode == "ul") {
        if (knitr::is_latex_output()) {
          paste0(
            "\\begin{itemize}\n",
            paste0("  \\item ", items, collapse = "\n"),
            "\n\\end{itemize}"
          )
        } else {
          paste0(
            "<ul>\n",
            paste0("  <li>", items, "</li>", collapse = "\n"),
            "\n</ul>"
          )
        }
      } else {
        # ordered list
        if (knitr::is_latex_output()) {
          if (mode == "ol-a") {
            paste0(
              "\\begin{enumerate}[label=\\alph*)]\n",
              paste0("  \\item ", items, collapse = "\n"),
              "\n\\end{enumerate}"
            )
          } else {
            paste0(
              "\\begin{enumerate}\n",
              paste0("  \\item ", items, collapse = "\n"),
              "\n\\end{enumerate}"
            )
          }
        } else {
          type_attr <- if (mode == "ol-a") " type=\"a\"" else ""
          paste0(
            "<ol", type_attr, ">\n",
            paste0("  <li>", items, "</li>", collapse = "\n"),
            "\n</ol>"
          )
        }
      }
    }

    for (ln in lines) {
      if (grepl("\\[\\[ul\\]\\]", ln))   { mode <- "ul";   buf <- character(0); next }
      if (grepl("\\[\\[ol\\]\\]", ln))   { mode <- "ol";   buf <- character(0); next }
      if (grepl("\\[\\[ol-a\\]\\]", ln)) { mode <- "ol-a"; buf <- character(0); next }

      if (grepl("\\[\\[/ul\\]\\]", ln) || grepl("\\[\\[/ol\\]\\]", ln) || grepl("\\[\\[/ol-a\\]\\]", ln)) {
        out <- c(out, flush_list(buf, mode))
        mode <- NULL
        buf <- character(0)
        next
      }

      if (!is.null(mode)) {
        if (grepl("^\\s*[-*]\\s+", ln) || grepl("^\\s*\\d+[\\.)]\\s+", ln)) buf <- c(buf, ln)
        next
      }

      out <- c(out, ln)
    }

    paste(out, collapse = "\n")
  })
}

# Helper: replace Markdown inline code spans (single backticks) inside descriptions
# with output-specific markup.
fmt_inline_code <- function(s, code_fmt_in = function(x) code_fmt(x)) {
  s <- unname(s)

  m <- gregexpr("`([^`]+)`", s, perl = TRUE)
  hits <- regmatches(s, m)

  if (length(hits) == 0) return(s)

  # Replace each matched `...` with code_fmt(inner)
  regmatches(s, m) <- lapply(hits, function(v) {
    vapply(v, function(tok) {
      inner <- gsub("^`|`$", "", tok)
      code_fmt_in(inner)
    }, character(1))
  })

  s
}

# Helper: normalize Unicode punctuation for LaTeX table rendering.
latex_text_normalize <- function(x) {
  x <- unname(x)
  x <- gsub("\u201C", "``", x, fixed = TRUE)  # left double quote
  x <- gsub("\u201D", "''", x, fixed = TRUE)  # right double quote
  x <- gsub("\u2018", "`",  x, fixed = TRUE)  # left single quote
  x <- gsub("\u2019", "'",  x, fixed = TRUE)  # right single quote
  x
}

render_arg_table <- function(args, desc, caption = NULL,
                             w1 = 0.26, w2 = 0.68, arraystretch = 1.1) {
  args <- unname(args)
  desc <- unname(desc)

  df <- data.frame(
    Argument = unname(vapply(args, code_fmt, character(1))),
    Description = unname(fmt_inline_code(fmt_lists(desc))),
    stringsAsFactors = FALSE,
    check.names = FALSE
  )

  if (knitr::is_latex_output()) {
    df$Argument <- latex_text_normalize(df$Argument)
    df$Description <- latex_text_normalize(df$Description)

    # Use wrapping paragraph columns; first column right-justified
    colspec <- c(
      sprintf(">{\\raggedleft\\arraybackslash}p{%.2f\\linewidth}", w1),
      sprintf("p{%.2f\\linewidth}", w2)
    )

    tab <- knitr::kable(
      df,
      format = "latex",
      booktabs = TRUE,
      longtable = TRUE,
      escape = FALSE,
      row.names = FALSE,
      col.names = c("Argument", "Description"),
      align = colspec,
      caption = caption
    )

    # Slightly nicer spacing, scoped to this table only
    return(knitr::asis_output(
      paste0("\\renewcommand{\\arraystretch}{", arraystretch, "}",
             tab)
    ))
  }

  # HTML stays as-is
  knitr::kable(
    df,
    format = "html",
    escape = FALSE,
    row.names = FALSE,
    col.names = c("Argument", "Description"),
    align = c("r", "l"),
    caption = caption
  )
}



