  improved_simulated_mpp <- simulate_mpp(
    process = "self_correcting",
    process_fit = if (inherits(estimated_sc_update, "ldmppr_fit")) estimated_sc_update else as.numeric(estimated_sc_update$solution),
    t_min = 0,
    t_max = 1,
    mark_model = improved_example_trained_mark_model,
    raster_list = scaled_rasters,
    scaled_rasters = TRUE,
    include_comp_inds = TRUE,
    competition_radius = 10,
    edge_correction = "none",
    thinning = TRUE,
    seed = 11001
  )

  initial_simulated_mpp <- simulate_mpp(
    process = "self_correcting",
    process_fit = if (inherits(estimated_sc, "ldmppr_fit")) estimated_sc else as.numeric(estimated_sc$solution),
    t_min = 0,
    t_max = 1,
    mark_model = example_trained_mark_model,
    raster_list = scaled_rasters,
    scaled_rasters = TRUE,
    include_comp_inds = TRUE,
    competition_radius = 10,
    edge_correction = "none",
    thinning = TRUE,
    seed = 11002
  )
}

ref_plot <- plot_mpp(
  mpp_data = reference_data,
  pattern_type = "reference"
)

improved_sim_plot <- plot(
  improved_simulated_mpp,
  pattern_type = "simulated"
)

initial_sim_plot <- plot(
  initial_simulated_mpp,
  pattern_type = "simulated"
)

hist_data <- data.frame(mark_data = c(reference_data$marks,
                                      improved_simulated_mpp$mpp$marks,
                                      initial_simulated_mpp$mpp$marks),
                        pattern_type = c(rep("Reference Mark Distribution",
                                             reference_data$n),
                                         rep("Improved Simulated Mark Distribution",
                                             improved_simulated_mpp$mpp$n),
                                         rep("Initial Simulated Mark Distribution",
                                             initial_simulated_mpp$mpp$n))
) %>%
  dplyr::mutate(pattern_type = factor(pattern_type,
                                      levels = c("Reference Mark Distribution",
                                                 "Improved Simulated Mark Distribution",
                                                 "Initial Simulated Mark Distribution")))

hist_plot <- ggplot(hist_data, aes(x = mark_data)) +
  geom_histogram(binwidth = 100, position = "identity",
                 alpha = 0.75, color = "black", linewidth = .25) +
  facet_wrap(~pattern_type, nrow = 1) +
  labs(x = "Mark", y = "Count") +
  theme(strip.text = element_text(size=12))

plot_design <- c("
                 111122223333
                 111122223333
                 111122223333
                 111122223333
                 444444444444
                 555555555555
                 555555555555
                 555555555555
                 555555555555")

data_plot <- (ref_plot +
                ggplot2::scale_size(breaks = c(0, 200, 400, 600, 800, 1000, 1200)) +
                ggplot2::theme(legend.position = "bottom")) +
  (improved_sim_plot +
     ggplot2::scale_size(breaks = c(0, 200, 400, 600, 800, 1000, 1200)) +
     ggplot2::theme(legend.position = "none") +
     ggplot2::labs(title = "Improved Simulated Data")) +
  (initial_sim_plot +
     ggplot2::scale_size(breaks = c(0, 200, 400, 600, 800, 1000, 1200)) +
     ggplot2::theme(legend.position = "none") +
     ggplot2::labs(title = "Initial Simulated Data")) +
  guide_area() +
  hist_plot +
  plot_layout(design = plot_design, guides = "collect") +
  plot_annotation(tag_levels = 'a', tag_suffix = ")")


